import app from './app';
import ajax from '@/utils/ajax';
import { Message } from "@arco-design/web-react";
import userStore from './userStore';
import { ProjectExtraInfo, ProjectInfo } from '@/types/project';
import { action, observable, makeObservable } from 'mobx';
import language from './language';
import user from "@code/store/user";



class Store {
    @observable extraInfo: ProjectExtraInfo = { 
        customVariables: []
    };

    @action assignExtraInfo = (data: Partial<ProjectExtraInfo>) => {
        this.extraInfo = { ...this.extraInfo, ...data };
    }

    /**
     * @保存插件信息
     */
    savaExtraInfo = () => {
        return ajax.post('/apijson/put', {
            Project: {
                id: this.info.id,
                extraInfo: this.extraInfo,
            }
        })
    }

    info:ProjectInfo = {
    };

    setInfo = (data) => {
        this.info = data;
        this.assignExtraInfo(data.extraInfo || {})
    }


    // 获取用户信息
    getProjectInfo = (id: string) => {
        app.appId = id;
        app.tenantId = id;
        return ajax.post('/dev/getProjectInfo', {
            projectId: id
        }).then((res) => {
            if(!res.info){
                Message.success("当前插件不存在，或没有权限");
                throw `${id} 插件获取失败`
            }
            this.setInfo(res.info);
            userStore.setDevToken(res.token);
            return Promise.all([
                // dev 环境，写入开发账号
                ajax.post('/dev/UserLogin', {
                    loginname: 'admin',
                }).then((res) => {
                    if(res.data){
                        user.setInfo(res.data);
                    }
                }).catch(() => {
                    
                }),
                // 加载当前项目多语言环境
                language.reloadProject(),
            ])
        })
    }

    constructor() {
        makeObservable(this);
    }
}

export default new Store();